  {x: 230, y: 230, width: 15, height: 70, angle: -45},
  {x: 210, y: 240, width: 10, height: 60, angle: -60},
  {x: 190, y: 250, width: 12, height: 50, angle: -75},
  {x: 170, y: 260, width: 18, height: 40, angle: -90},
  {x: 150, y: 270, width: 25, height: 30, angle: -105},
  {x: 130, y: 280, width: 30, height: 20, angle: -120},
  {x: 110, y: 290, width: 20, height: 15, angle: -135}
];

tailFeathers.forEach(f => {
  const [sx, sy] = [f.x, f.y];
  const [ex, ey] = [f.x + f.width * Math.cos(f.angle * Math.PI/180), f.y + f.height * Math.sin(f.angle * Math.PI/180)];

  // Feather shaft
  ctx.fillStyle = '#1E90FF';
  ctx.fillRect(sx, sy, f.width, f.height);

  // Feather barbules
  ctx.fillStyle = '#191970';
  for(let i = 0; i < 5; i++) {
    const dx = f.width * (i/5) * Math.cos(f.angle * Math.PI/180);
    const dy = f.height * (i/5) * Math.sin(f.angle * Math.PI/180);
    ctx.fillRect(ex + dx - 2, ey + dy - 2, 4, 4);
  }
});

