// Draw stack of vinyl records
const records = 8;
const baseY = 300;
const recordWidth = 150;
const recordHeight = 100;
const margin = 20;
const centerX = W / 2;

// Draw base rectangle for stack
ctx.fillStyle = '#222';
ctx.fillRect(centerX - recordWidth/2, baseY, recordWidth, records * recordHeight + margin * (records - 1));

// Draw vinyl records
for (let i = 0; i < records; i++) {
    const y = baseY - i * (recordHeight + margin);

    // Outer edge
    ctx.fillStyle = '#333';
    ctx.beginPath();
    ctx.arc(centerX, y + recordHeight/2, recordWidth/2, 0, Math.PI * 2);
    ctx.fill();

    // Center
    ctx.fillStyle = '#000';
    ctx.beginPath();
    ctx.arc(centerX, y + recordHeight/2, recordWidth/4, 0, Math.PI * 2);
    ctx.fill();

    // Grooves
    ctx.strokeStyle = '#555';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let j = 0; j < 8; j++) {
        const angle = (j/8) * Math.PI * 2;
        const x1 = centerX + Math.cos(angle) * (recordWidth/2 - 5);
        const y1 = y + recordHeight/2 + Math.sin(angle) * (recordHeight/2 - 5);
        const x2 = centerX + Math.cos(angle) * (recordWidth/2 + 5);
        const y2 = y + recordHeight/2 + Math.sin(angle) * (recordHeight/2 + 5);
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
    }
    ctx.stroke();

    // Label
    ctx.fillStyle = '#fff';
    ctx.font = '12px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(`YEAR ${i+1}`, centerX, y + recordHeight/2 + 15);
}

