// Draw concentric circles
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

// Define colors
const colors = [
  '#ffd500', // orange
  '#4caf50', // green
  '#9c27b0', // purple
  '#ff9800', // amber
  '#795548', // brown
  '#2196f3'  // blue
];

// Draw circles with gradient fill
for (let r = 20; r <= maxRadius; r += 20) {
  const gradient = ctx.createRadialGradient(
    centerX, centerY,
    r - 10, centerX, centerY,
    r + 10
  );

  let offset = 0;
  for (let i = 0; i < 6; i++) {
    gradient.addColorStop(offset, colors[i]);
    offset += 0.166;
  }

  ctx.beginPath();
  ctx.arc(centerX, centerY, r, 0, Math.PI * 2);
  ctx.fillStyle = gradient;
  ctx.fill();

  // Add subtle border to each circle
  ctx.strokeStyle = '#1a1a2e';
  ctx.lineWidth = 2;
  ctx.stroke();
}

// Draw radial lines
ctx.strokeStyle = '#ffffff';
ctx.lineWidth = 1;
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const startX = centerX + Math.cos(angle) * maxRadius;
  const startY = centerY + Math.sin(angle) * maxRadius;
  const endX = centerX + Math.cos(angle) * (maxRadius + 30);
  const endY = centerY + Math.sin(angle) * (maxRadius + 30);

  ctx.beginPath();
  ctx.moveTo(startX, startY);
  ctx.lineTo(endX, endY);
  ctx.stroke();
}

// Draw inner triangles
ctx.fillStyle = '#ff9800';
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const x1 = centerX + Math.cos(angle) * 60;
  const y1 = centerY + Math.sin(angle) * 60;
  const x2 = centerX + Math.cos(angle + Math.PI/4) * 60;
  const y2 = centerY + Math.sin(angle + Math.PI/4) * 60;
  const x3 = centerX + Math.cos(angle - Math.PI/4) * 60;
  const y3 = centerY + Math.sin(angle - Math.PI/4) * 60;

  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.lineTo(x3, y3);
  ctx.closePath();
  ctx.fill();
}

