// Draw a cool-toned fractal spiral
ctx.fillStyle = '#0a0a2a';
ctx.fillRect(0, 0, W, H);

const drawSpiral = (x, y, len, angle, depth) => {
    if (depth === 0) return;

    // Calculate new position
    const newX = x + len * Math.cos(angle);
    const newY = y + len * Math.sin(angle);

    // Draw segment
    ctx.strokeStyle = `hsl(${20 + depth * 15}, 70%, ${50 - depth * 5}%)`;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(newX, newY);
    ctx.stroke();

    // Recursive calls for each quadrant
    drawSpiral(newX, newY, len * 0.75, angle + Math.PI/4, depth - 1);
    drawSpiral(newX, newY, len * 0.75, angle - Math.PI/4, depth - 1);
};

