ctx.fill();

// Tentacles
ctx.fillStyle = '#fff';
for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const x1 = cx + Math.cos(angle) * (radius + 20);
    const y1 = cy + Math.sin(angle) * (radius + 20);

    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x1 + Math.cos(angle) * 30, y1 + Math.sin(angle) * 30);
    ctx.lineTo(x1 + Math.cos(angle) * 20, y1 + Math.sin(angle) * 20);
    ctx.closePath();
    ctx.fill();
}

